// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _test(uint256 amount1, uint256 amount2) internal {
        amount1 = bound(amount1, 0, 1000000000000000000000000000000);
        amount2 = bound(amount2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount1 == 10);
        vm.assume(amount2 == 10);
        vm.assume(address(this).balance >= amount1 + amount2);
        vm.assume(uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2 != 0);
        uint256 potBefore;
        try c.pot() returns (uint256 __r) { potBefore = __r; } catch { return; }
        try c.play{value: amount1}() {} catch { return; }
        try c.play{value: amount2}() {} catch { return; }
        uint256 potAfter;
        try c.pot() returns (uint256 __r) { potAfter = __r; } catch { return; }
        assertTrue(potAfter == potBefore + amount1 + amount2);
    }

    function testFuzz_test(uint256 amount1, uint256 amount2) public {
        _test(amount1, amount2);
    }

    receive() external payable {}
}
